export type OrderStatus = 'placed' | 'paid' | 'packed' | 'shipped' | 'delivered';

export interface OrderLine {
  productId: string;
  quantity: number;
}

const STATUS_ORDER: OrderStatus[] = ['placed', 'paid', 'packed', 'shipped', 'delivered'];

export class Order {
  private status: OrderStatus = 'placed';
  readonly createdAt: Date;

  constructor(
    readonly id: string,
    readonly lines: OrderLine[]
  ) {
    this.createdAt = new Date();
  }

  getStatus(): OrderStatus {
    return this.status;
  }

  canTransitionTo(newStatus: OrderStatus): boolean {
    const currentIndex = STATUS_ORDER.indexOf(this.status);
    const newIndex = STATUS_ORDER.indexOf(newStatus);
    return newIndex === currentIndex + 1;
  }

  transitionTo(newStatus: OrderStatus): void {
    if (!this.canTransitionTo(newStatus)) {
      throw new Error(`Cannot transition from ${this.status} to ${newStatus}`);
    }
    this.status = newStatus;
  }

  canBeCancelled(): boolean {
    return this.status !== 'shipped' && this.status !== 'delivered';
  }
}

=====SOURCE-END=====

